-- Hoa — demo account data (generated from the testing build's mock HISTORY
-- and CHATS, so the account looks like what participants saw).
-- Run after seed.sql. Re-runnable: it clears the demo user's rows first.
-- The account itself is created through Auth, not here.

do $$
declare
  uid uuid := (select id from auth.users where email = 'joengy44@gmail.com');
begin
  if uid is null then
    raise exception 'demo account joengy44@gmail.com does not exist yet';
  end if;

  delete from movement_sessions where user_id = uid;
  delete from plan_rsvps where user_id = uid;
  delete from saved_items where user_id = uid;
  delete from messages where conversation_id in (select id from conversations where slug in ('c1','c2','c3','c4'));
  delete from conversation_members where user_id = uid;

    select id, uid from conversations where slug in ('c1','c2','c3','c4');



    select id, uid, case slug when 'u1' then 'going' else 'saved' end from plans where slug in ('u1','u2');
end $$;
