  insert into movement_sessions (user_id, type, title, min, kcal, intensity, mood, location, led_by, led_by_idx, with_who, notes, occurred_at) values (uid, 'vr', $j${"en":"Kauri forest walk","zh":"贝壳杉森林漫步"}$j$::jsonb, 10, 45, 'gentle', $j${"en":"calmer","zh":"更平静"}$j$::jsonb, $j${"en":"Home · VR (1.5 m clear space)","zh":"居家 · VR（1.5 米空地）"}$j$::jsonb, $j${"en":"Mei-Lin (voice guide)","zh":"美琳（语音引导）"}$j$::jsonb, 3, array[]::text[], $j${"en":"You paused near the kauri grove, then kept walking. Breath stayed steady throughout.","zh":"你在贝壳杉林前停了一下，然后继续走。呼吸全程平稳。"}$j$::jsonb, now() - interval '0 day');
  insert into movement_sessions (user_id, type, title, min, kcal, intensity, mood, location, led_by, led_by_idx, with_who, notes, occurred_at) values (uid, 'outdoor', $j${"en":"Cornwall Park slow walk","zh":"康沃尔公园慢步走"}$j$::jsonb, 40, 150, 'steady', $j${"en":"restored","zh":"恢复了"}$j$::jsonb, $j${"en":"Cornwall Park · rose garden","zh":"康沃尔公园 · 玫瑰园"}$j$::jsonb, $j${"en":"Mei-Lin","zh":"美琳"}$j$::jsonb, 3, array[$t$Sarah$t$,$t$Elena$t$,$t$Priya$t$]::text[], $j${"en":"A flat loop. You walked the full 40 minutes and rested twice on the benches.","zh":"平坦的环线。你走完了整整 40 分钟，在长椅上休息了两次。"}$j$::jsonb, now() - interval '1 day');
  insert into movement_sessions (user_id, type, title, min, kcal, intensity, mood, location, led_by, led_by_idx, with_who, notes, occurred_at) values (uid, 'home', $j${"en":"Shoulder & neck reset","zh":"肩颈舒缓"}$j$::jsonb, 8, 30, 'gentle', $j${"en":"looser","zh":"放松了"}$j$::jsonb, $j${"en":"Living room · seated","zh":"客厅 · 坐姿"}$j$::jsonb, $j${"en":"Aroha (voice guide)","zh":"Aroha（语音引导）"}$j$::jsonb, 1, array[]::text[], $j${"en":"Quick reset after a long screen day. Shoulders dropped noticeably by the end.","zh":"盯了一天屏幕后的快速舒缓。结束时肩膀明显放松。"}$j$::jsonb, now() - interval '3 day');
  insert into movement_sessions (user_id, type, title, min, kcal, intensity, mood, location, led_by, led_by_idx, with_who, notes, occurred_at) values (uid, 'outdoor', $j${"en":"Harbour evening walk","zh":"海港傍晚散步"}$j$::jsonb, 35, 130, 'steady', $j${"en":"peaceful","zh":"平静"}$j$::jsonb, $j${"en":"Mission Bay waterfront","zh":"使命湾海滨"}$j$::jsonb, $j${"en":"Self-guided","zh":"自助"}$j$::jsonb, null, array[$t$Elena$t$]::text[], $j${"en":"Slower than your morning walks. You stopped to watch the sunset for a while.","zh":"比早晨的散步更慢。你停下来看了一会儿日落。"}$j$::jsonb, now() - interval '5 day');
  insert into movement_sessions (user_id, type, title, min, kcal, intensity, mood, location, led_by, led_by_idx, with_who, notes, occurred_at) values (uid, 'vr', $j${"en":"Lakeside rhythm (VR)","zh":"湖畔律动（VR）"}$j$::jsonb, 12, 70, 'strong', $j${"en":"energised","zh":"充满活力"}$j$::jsonb, $j${"en":"Home · VR (2 m space)","zh":"居家 · VR（2 米空地）"}$j$::jsonb, $j${"en":"Sun (voice guide)","zh":"Sun（语音引导）"}$j$::jsonb, 4, array[]::text[], $j${"en":"First time at 'steady' intensity in VR. You took a 1-minute pause halfway and finished.","zh":"第一次在 VR 中尝试「平稳」强度。中途暂停了 1 分钟，最后完成了练习。"}$j$::jsonb, now() - interval '6 day');
  insert into movement_sessions (user_id, type, title, min, kcal, intensity, mood, location, led_by, led_by_idx, with_who, notes, occurred_at) values (uid, 'social', $j${"en":"Beginner badminton","zh":"初学者羽毛球"}$j$::jsonb, 45, 220, 'strong', $j${"en":"tired but happy","zh":"累但开心"}$j$::jsonb, $j${"en":"Sandringham Community House","zh":"桑德灵厄姆社区中心"}$j$::jsonb, $j${"en":"Community House host","zh":"社区中心主持"}$j$::jsonb, null, array[$t$Hana$t$,$t$Lien$t$]::text[], $j${"en":"First real game. Many laughs. Knees felt it the next day — but in a good way.","zh":"第一次真正比赛。笑得很多。第二天膝盖有感觉——但是好的那种。"}$j$::jsonb, now() - interval '9 day');
  insert into movement_sessions (user_id, type, title, min, kcal, intensity, mood, location, led_by, led_by_idx, with_who, notes, occurred_at) values (uid, 'outdoor', $j${"en":"Beach clean-up walk","zh":"海滩清洁散步"}$j$::jsonb, 50, 180, 'steady', $j${"en":"connected","zh":"有连接感"}$j$::jsonb, $j${"en":"Mission Bay shore","zh":"使命湾海岸"}$j$::jsonb, $j${"en":"Blue Coast group","zh":"蓝海岸小组"}$j$::jsonb, 2, array[$t$Sarah$t$,$t$Priya$t$,$t$Hana$t$]::text[], $j${"en":"Walked + tidied. Surprising how good carrying a small bag felt.","zh":"边走边清理。意外地，提一个小袋子感觉很好。"}$j$::jsonb, now() - interval '12 day');
  insert into movement_sessions (user_id, type, title, min, kcal, intensity, mood, location, led_by, led_by_idx, with_who, notes, occurred_at) values (uid, 'vr', $j${"en":"Wake the upper body (VR)","zh":"唤醒上半身（VR）"}$j$::jsonb, 8, 35, 'gentle', $j${"en":"awake","zh":"清醒"}$j$::jsonb, $j${"en":"Home · seated","zh":"居家 · 坐姿"}$j$::jsonb, $j${"en":"Aroha (voice guide)","zh":"Aroha（语音引导）"}$j$::jsonb, 1, array[]::text[], $j${"en":"Two short sessions back-to-back. Stiffness in the neck eased a lot.","zh":"连续做了两节短练习。颈部僵硬大大缓解。"}$j$::jsonb, now() - interval '18 day');
  insert into movement_sessions (user_id, type, title, min, kcal, intensity, mood, location, led_by, led_by_idx, with_who, notes, occurred_at) values (uid, 'outdoor', $j${"en":"Sunrise park yoga","zh":"日出公园瑜伽"}$j$::jsonb, 30, 90, 'gentle', $j${"en":"grounded","zh":"安定"}$j$::jsonb, $j${"en":"Cornwall Park · rose garden","zh":"康沃尔公园 · 玫瑰园"}$j$::jsonb, $j${"en":"Mei-Lin","zh":"美琳"}$j$::jsonb, 3, array[$t$Mei-Lin$t$,$t$Hana$t$]::text[], $j${"en":"Cool morning air. Calmed your breath for the rest of the day.","zh":"清凉的清晨空气。整天的呼吸都比较平静。"}$j$::jsonb, now() - interval '26 day');
